// This readable worker replaces DocFX's fixed-name search worker. The bundled
// English Lunr pipeline removes Cyrillic characters; its available language
// plugins do not cover all five documentation languages. Keep DocFX's message
// protocol while searching this small site's Unicode text directly.

let documents = [];
let ready = false;

function normalize(text) {
  return String(text || '')
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLowerCase();
}

function words(text) {
  // DocFX prefixes query terms with '+'. Tokenization removes that operator as
  // well as punctuation, while retaining letters from every supported language.
  return normalize(text).match(/[\p{L}\p{N}_]+/gu) || [];
}

async function loadIndex() {
  ready = false;
  const response = await fetch('../index.json');
  if (!response.ok) throw new Error(`Cannot load search index: ${response.status}`);
  const index = await response.json();
  documents = Object.values(index).map(document => ({
    document,
    title: normalize(document.title),
    keywords: normalize(document.keywords),
    summary: normalize(document.summary)
  }));
  ready = true;
  postMessage({ e: 'index-ready' });
}

function search(query) {
  const terms = [...new Set(words(query))];
  if (!terms.length) return [];

  const hits = [];
  for (const entry of documents) {
    let score = 0;
    for (const term of terms) {
      // Every requested word must occur. Partial matches also make long C#
      // identifiers discoverable without requiring the complete method name.
      const weight = entry.title.includes(term) ? 50
        : entry.keywords.includes(term) ? 40
        : entry.summary.includes(term) ? 20 : 0;
      if (!weight) {
        score = 0;
        break;
      }
      score += weight;
    }
    if (score) hits.push({ document: entry.document, score });
  }

  return hits.sort((a, b) => b.score - a.score
    || a.document.href.localeCompare(b.document.href))
    .map(hit => hit.document);
}

self.onmessage = event => {
  if (event.data.init) {
    // The worker URL is scoped to the current language. Loading its own index
    // avoids sharing cached results across languages on the same Pages domain.
    loadIndex().catch(error => console.error(error));
  } else if (ready && typeof event.data.q === 'string') {
    postMessage({ e: 'query-ready', d: search(event.data.q) });
  }
};
